/**
  * 検索結果から宛先の応答を作成する
  * @param {String} key result のキー（検索したメールアドレス）
  * @param {Object} entry contact または error
  * @return {HttpResponseWrapper}
  */
const createSearchResponse = (key, entry) => {
    return httpClient.createHttpResponse(200, 'application/json', JSON.stringify({result: {[key]: entry}}));
};

/**
  * 成功
  * 既存の宛先がメールアドレス以外の識別子を持つ場合、それらも指定して更新する
  * カスタムフィールドあり
  */
test('Succeed - Other identifiers of the existing contact are set', () => {
    const email = 'test@example.com';
    const fieldConfigMap = new Map();
    fieldConfigMap.set(1, {name: 'field_1', type: 'STRING_TEXTFIELD', value: 'フィールドの値'});
    prepareConfigs(email, fieldConfigMap);

    const contact = {
        email,
        custom_fields: {'1T': 'フィールドの値'},
        phone_number_id: '+819012345678',
        external_id: 'ext1',
        anonymous_id: 'anon1'
    };
    let reqCount = 0;
    httpClient.setRequestHandler((request) => {
        if (reqCount === 0) {
            assertGetAllCustomFieldsRequest(request);
            reqCount++;
            return httpClient.createHttpResponse(200, 'application/json', JSON.stringify(ALL_CUSTOM_FIELDS_RESPONSE));
        }
        if (reqCount === 1) {
            assertSearchRequest(request, email);
            reqCount++;
            return createSearchResponse(email, {contact: {
                id: 'contact1', email, first_name: 'Jane',
                phone_number_id: '+819012345678', external_id: 'ext1', anonymous_id: 'anon1'
            }});
        }
        if (reqCount === 2) {
            assertUpsertRequest(request, contact);
            reqCount++;
            return httpClient.createHttpResponse(202, 'application/json', '{"job_id": "job10"}');
        }
        assertCheckStatusRequest(request, 'job10');
        return httpClient.createHttpResponse(200, 'application/json', '{"status": "completed"}');
    });
    expect(main()).toEqual(undefined);
    expect(reqCount).toEqual(3);
});

/**
  * 成功
