/**
  * 成功
  * 検索結果が 200 でも、メールアドレスの結果が error の場合は、識別子を追加せずに更新する
  */
test('Succeed - Search result of the email is an error', () => {
    const email = 'test@example.com';
    prepareConfigs(email, new Map()); // カスタムフィールドの指定なし

    let reqCount = 0;
    httpClient.setRequestHandler((request) => {
        if (reqCount === 0) {
            assertSearchRequest(request, email);
            reqCount++;
            return createSearchResponse(email, {error: 'not found'});
        }
        if (reqCount === 1) {
            assertUpsertRequest(request, {email});
            reqCount++;
            return httpClient.createHttpResponse(202, 'application/json', '{"job_id": "job13"}');
        }
        assertCheckStatusRequest(request, 'job13');
        return httpClient.createHttpResponse(200, 'application/json', '{"status": "completed"}');
    });
    expect(main()).toEqual(undefined);
    expect(reqCount).toEqual(2);
});

