/**
  * ジョブが異常終了し、errors_url からエラー詳細を取得してログ出力する
  */
test('Fail to complete upserting - error details are logged', () => {
    const email = createString(MAX_EMAIL_LENGTH);
    prepareConfigs(email, new Map()); // カスタムフィールドの指定なし

    const errorsUrl = 'https://example.com/errors.csv?X-Amz-Signature=abc';
    const csv = 'primary_email,errors_occurred\na@example.com,"some error"';
    let reqCount = 0;
    let errorsUrlRequested = false;
    httpClient.setRequestHandler((request) => {
        const searchResponse = respondToSearchRequest(request);
        if (searchResponse !== null) {
            return searchResponse;
        }
        if (reqCount === 0) {
            assertUpsertRequest(request, {email});
            reqCount++;
            return httpClient.createHttpResponse(202, 'application/json', '{"job_id": "job1"}');
        }
        if (reqCount === 1) {
            assertCheckStatusRequest(request, 'job1');
            reqCount++;
            return httpClient.createHttpResponse(200, 'application/json',
                JSON.stringify({status: 'failed', results: {errors_url: errorsUrl}}));
        }
        // errors_url へのリクエスト
        expect(request.url).toEqual(errorsUrl);
        expect(request.method).toEqual('GET');
        errorsUrlRequested = true;
        return httpClient.createHttpResponse(200, 'text/csv', csv);
    });

    assertError(main, 'Failed to complete upserting the contact.');
    expect(reqCount).toEqual(2);
    expect(errorsUrlRequested).toEqual(true);
});

