/**
  * 2 回目のステータス確認で、ジョブが異常終了（errors_url あり）
  * proceed() でも errors_url からエラー詳細を取得する
  */
test('Fail to complete upserting in proceed() - error details are fetched', () => {
    const email = createString(MAX_EMAIL_LENGTH);
    prepareConfigs(email, new Map()); // カスタムフィールドの指定なし

    const errorsUrl = 'https://example.com/errors.csv?X-Amz-Signature=abc';
    let reqCount = 0;
    httpClient.setRequestHandler((request) => {
        const searchResponse = respondToSearchRequest(request);
        if (searchResponse !== null) {
            return searchResponse;
        }
        if (reqCount === 0) {
            assertUpsertRequest(request, {email});
            reqCount++;
            return httpClient.createHttpResponse(202, 'application/json', '{"job_id": "job7"}');
        }
        assertCheckStatusRequest(request, 'job7');
        return httpClient.createHttpResponse(200, 'application/json', '{"status": "pending"}');
    });
    expect(main()).toEqual(false);
    expect(engine.restoreTemporaryData()).toEqual('job7');

    let errorsUrlRequested = false;
    httpClient.setRequestHandler((request) => {
        if (request.url === errorsUrl) {
            expect(request.method).toEqual('GET');
            errorsUrlRequested = true;
            return httpClient.createHttpResponse(200, 'text/csv', 'primary_email,errors_occurred\na@example.com,"some error"');
        }
        assertCheckStatusRequest(request, 'job7');
        return httpClient.createHttpResponse(200, 'application/json',
            JSON.stringify({status: 'errored', results: {errors_url: errorsUrl}}));
    });
    assertError(proceed, 'Failed to complete upserting the contact.');
    expect(errorsUrlRequested).toEqual(true);
});

